+namespace TextKit.Core;
+
+public static class App
+{
+    public static int Run(string[] args, IReadOnlyList<ICommand> commands, TextWriter output, TextWriter error)
+    {
+        if (args.Length == 0 || args[0] is "help" or "--help" or "-h")
+        {
+            output.WriteLine("Usage: textkit <command> [arguments]");
+            output.WriteLine();
+            output.WriteLine("Commands:");
+
+            var width = commands.Count == 0 ? 0 : commands.Max(command => command.Usage.Length);
+            foreach (var command in commands.OrderBy(command => command.Name, StringComparer.Ordinal))
+            {
+                output.WriteLine($"  {command.Usage.PadRight(width)}   {command.Description}");
+            }
+
+            return ExitCodes.Ok;
+        }
+
+        foreach (var command in commands)
+        {
+            if (string.Equals(args[0], command.Name, StringComparison.Ordinal))
+            {
+                try
+                {
+                    return command.Run(args[1..], output);
+                }
+                catch (CommandException exception)
+                {
+                    error.WriteLine($"error: {exception.Message}");
+                    return exception.ExitCode;
+                }
+            }
+        }
+
+        error.WriteLine($"error: unknown command '{args[0]}'");
+        return ExitCodes.Usage;
+    }
+}
